import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

/**
 * Scratch investigation harness (Routine C): reproduces the ThemeQueryBenchmark two-fork sequence for HIGHLY_CONNECTED
 * query 10 inside one JVM (fork 1 janino=false, fork 2 janino=true) so the cost-model sidecar handoff is faithful.
 * Iterations use plain evaluate() so excursions cost their true benchmark-equivalent time (telemetry mode records
 * adjacency-access descriptions per existence probe and grinds the slow arm by orders of magnitude); the adaptive
 * decision is sampled with a bounded telemetry explain only on provably-fast iterations and once right after each
 * excursion. The user's sidecar is restored from a fixed backup path even across killed runs.
 */
public class ThemeQueryAdaptiveSwitchTraceTest {

	private static final Pattern EXECUTION_PATH = Pattern.compile("nativeExecutionPath=(\\w+)");
	private static final Pattern DECISION = Pattern.compile("nativeAdaptiveCostDecision=(.*?), native[A-Z]");
	private static final Pattern DECLINES = Pattern
			.compile("nativeStrategyDeclines=(.*?), (?:metricOrigin|hasNext|native[A-Z])");
	private static final Pattern PROPOSAL_COSTS = Pattern.compile("nativeStrategyProposalCosts=(.*?), native[A-Z]");

	private static final Path USER_SIDECAR_BACKUP = Path
			.of("/private/tmp/claude-501/-Users-havardottestad-Documents-Programming-rdf4j/"
					+ "8ce99f1a-4c08-441e-bdce-841c434fc863/scratchpad/cost-model-user-original.lncm");

	@Test
	@Disabled("investigation harness: run on demand only — needs the fixed 2.2 GB theme store and takes minutes")
	@Timeout(value = 20, unit = TimeUnit.MINUTES)
	public void traceHc10JaninoDecisions() throws Exception {
		File storeDirectory = new File("target/lmdb-theme-query-benchmark/complete");
		assumeTrue(storeDirectory.isDirectory(), "fixed benchmark store not present");

		Path sidecar = storeDirectory.toPath().resolve("cost-model.lncm");
		if (!Files.exists(USER_SIDECAR_BACKUP) && Files.exists(sidecar)) {
			Files.copy(sidecar, USER_SIDECAR_BACKUP);
		}

		String previousEnabled = System.getProperty("rdf4j.lmdb.janinoCodegen.enabled");
		String previousThreshold = System.getProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		String previousSynchronous = System.getProperty("rdf4j.lmdb.janinoCodegen.synchronous");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");

		String query = ThemeQueryCatalog.queryFor(Theme.HIGHLY_CONNECTED, 10);
		try {
			System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "false");
			runPhase("P1-janinoOff", storeDirectory, query, 5, 100L);
			System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
			System.setProperty("rdf4j.lmdb.janinoCodegen.debug", "true");
			System.setProperty("rdf4j.lmdb.janinoCodegen.failOnError", "true");
			runPhase("P2-janinoOn", storeDirectory, query, 6, 100L);
		} finally {
			if (Files.exists(USER_SIDECAR_BACKUP)) {
				Files.copy(USER_SIDECAR_BACKUP, sidecar, StandardCopyOption.REPLACE_EXISTING);
			}
			restore("rdf4j.lmdb.janinoCodegen.enabled", previousEnabled);
			restore("rdf4j.lmdb.janinoCodegen.thresholdRows", previousThreshold);
			restore("rdf4j.lmdb.janinoCodegen.synchronous", previousSynchronous);
		}
	}

	private static void runPhase(String phase, File storeDirectory, String query, int iterations, long paceMillis)
			throws Exception {
		LmdbStoreConfig config = ConfigUtil.createConfig();
		config.setSketchEstimatorEnabled(false);
		SailRepository repository = new SailRepository(new LmdbStore(storeDirectory, config));
		long startNanos = System.nanoTime();
		int slowIterations = 0;
		try {
			for (int iteration = 1; iteration <= iterations; iteration++) {
				long iterationStart = System.nanoTime();
				long rows = 0;
				try (var connection = repository.getConnection()) {
					TupleQuery tupleQuery = connection.prepareTupleQuery(query);
					tupleQuery.setMaxExecutionTime(50);
					try (var result = tupleQuery.evaluate()) {
						while (result.hasNext()) {
							result.next();
							rows++;
						}
					}
				} catch (RuntimeException interrupted) {
					System.out.println("      !! evaluate aborted: " + interrupted);
				}
				long elapsedMillis = (System.nanoTime() - iterationStart) / 1_000_000L;
				long wallSeconds = (System.nanoTime() - startNanos) / 1_000_000_000L;
				boolean slow = elapsedMillis > 300L;
				System.out.printf("TRACE %s iter=%3d wall=%4ds elapsed=%6dms rows=%d%s%n", phase, iteration,
						wallSeconds, elapsedMillis, rows, slow ? "  <-- EXCURSION" : "");
				if (slow) {
					slowIterations++;
					sampleDecision(repository, query, "post-excursion");
					if (slowIterations >= 3) {
						System.out.println("      bail: 5 excursions captured");
						return;
					}
				} else if (iteration <= 3 || iteration % 5 == 0) {
					sampleDecision(repository, query, "steady");
				}
				System.out.flush();
				Thread.sleep(paceMillis);
			}
		} finally {
			repository.shutDown();
		}
	}

	/** Bounded telemetry sample: prints the current dispatch decision, giving up after 15 s if the model is stuck. */
	private static void sampleDecision(SailRepository repository, String query, String label) {
		long start = System.nanoTime();
		try (var connection = repository.getConnection()) {
			TupleQuery tupleQuery = connection.prepareTupleQuery(query);
			tupleQuery.setMaxExecutionTime(15);
			Explanation explain = tupleQuery.explain(Explanation.Level.Telemetry);
			String explanation = explain.toString();
			long ms = (System.nanoTime() - start) / 1_000_000L;
			System.out.println("      sample(" + label + " " + ms + "ms) path=" + first(EXECUTION_PATH, explanation));
			System.out.println("      decision=" + first(DECISION, explanation));
			System.out.println("      declines=" + first(DECLINES, explanation));
			System.out.println("      costs=" + first(PROPOSAL_COSTS, explanation));
			explanation.lines()
					.map(String::strip)
					.filter(line -> line.startsWith("invocation[") || line.startsWith("status:")
							|| line.startsWith("strategy:"))
					.forEach(line -> System.out.println("      | " + line));
		} catch (RuntimeException interrupted) {
			long ms = (System.nanoTime() - start) / 1_000_000L;
			System.out.println("      sample(" + label + " " + ms + "ms) ABORTED: " + interrupted);
		}
	}

	private static String first(Pattern pattern, String text) {
		Matcher matcher = pattern.matcher(text);
		return matcher.find() ? matcher.group(1) : "<absent>";
	}

	private static void restore(String property, String previousValue) {
		if (previousValue == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previousValue);
		}
	}
}
